mapper.update:
UPDATE HDOC_ADCA_MODIFICATION a
INNER JOIN HDOC_VARIABLES b ON a.VARIABLE = b.VARIABLE
SET a.NEWVAL = #{newval},
    a.UPDATE_DATETIME = NOW(),
    a.UPDATE_USER = #{updateUser},
    a.UPDATE_PROCESS = #{updateProcess}
WHERE a.CHNO = #{chno}
  AND a.SERIE = #{serie}
  AND b.DESCRIPTION = #{description}

mapper.select:
SELECT DOCTYPE, VERS, VARIABLE, NEWVAL
FROM HDOC_ADCA_MODIFICATION
WHERE SERIE = #{serie} AND CHNO = #{chno}
